WITH base AS (SELECT id, customer_id, store_id, channel, amount, discount, amount + shipping_fee AS amount_with_shipping, ADD_MONTHS(order_date, 3) AS order_date_plus_months FROM orders WHERE store_id IS NOT NULL), joined AS (SELECT e.*, d.region FROM base e JOIN stores d ON e.store_id = d.id), ranked AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY customer_id ORDER BY amount DESC, id) AS rn FROM joined QUALIFY rn = 1), scored AS (SELECT id, store_id, channel, order_date_plus_months, LEAD(amount_with_shipping) OVER (PARTITION BY region ORDER BY rn, id) AS next_amount_with_shipping, LAG(amount) OVER (PARTITION BY region ORDER BY rn, id) AS prev_amount, LEAD(amount) OVER (PARTITION BY region ORDER BY rn, id) AS next_amount, ROW_NUMBER() OVER (PARTITION BY region ORDER BY rn, id) AS row_seq FROM ranked), eligible AS (SELECT s.* FROM scored s WHERE NOT EXISTS (SELECT 1 FROM order_items ch WHERE ch.order_id = s.id AND ch.order_id IN (22, 31))) SELECT DATE_TRUNC('WEEK', order_date_plus_months) AS week_start, COUNT_IF(channel = 'partner') AS partner_events, SORT_ARRAY(COLLECT_SET(channel)) AS channel_list FROM eligible GROUP BY DATE_TRUNC('WEEK', order_date_plus_months) ORDER BY partner_events NULLS LAST
